            form.reset();
            successMessage.classList.remove('show');
            submitBtn.disabled = true;
            submitBtn.textContent = 'Continue';
            checkbox.removeAttribute('aria-invalid');
        }, 3000);
    });

    updateSubmitButtonState();
});
